-- ============================================================
-- Fix 6 first-batch (April 2026) mount downports that were
-- auto-named from their model/folder name instead of the real
-- retail name, and carried the generic shared Reins icon (68743).
-- Real identities resolved via Mount.db2 -> MountXDisplay ->
-- CreatureDisplayInfo -> CreatureModelData, matched by FileDataID
-- (these 6 use the ACTUAL retail model file, only the name was
-- a placeholder). New icon ids = 8000000+IconFileDataID scheme.
-- ============================================================

DELETE FROM `item_template` WHERE `entry` IN (300389,300391,300401,300402,300403,300404);

DELETE FROM `creature_template` WHERE `entry` IN (3461001,3461005,3461185,3461186,3461187,3461188);

DELETE FROM `dc_mount_definitions` WHERE `spell_id` IN (300700,300702,300731,300732,300733,300734);

